@pytest.mark.pre_alloc_mutable
def test_create2check_fields_in_initcode(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Check opcode values in create2 init code. Create2 called with different call types. CREATE2 inside CRETE2 inside CALL, CALLCODE, DELEGATECALL, STATICCALL << test values of  SENDER,address and so on.."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0xa94f5374fce5edbc8e2a8697c15331677e6ebf0b")
    contract = Address("0xb94f5374fce5edbc8e2a8697c15331677e6ebf0b")
    callee = Address("0x1000000000000000000000000000000000000000")
    callee_1 = Address("0x1100000000000000000000000000000000000000")
    callee_2 = Address("0x2000000000000000000000000000000000000000")
    callee_3 = Address("0x2200000000000000000000000000000000000000")
    callee_4 = Address("0x3000000000000000000000000000000000000000")
    callee_5 = Address("0x3300000000000000000000000000000000000000")
    callee_6 = Address("0x4000000000000000000000000000000000000000")
    callee_7 = Address("0x4400000000000000000000000000000000000000")
    callee_8 = Address("0xf000000000000000000000000000000000000000")
    callee_9 = Address("0xf200000000000000000000000000000000000000")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=1000000,
    )

    pre[callee] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.CALL(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, value=0x0, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0)
        + Op.STOP
    ),
    )
    pre[callee_1] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x24]
        + Op.CODECOPY(dest_offset=0x0, offset=0x13, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.POP(Op.CREATE2) + Op.STOP + Op.STOP + Op.INVALID
        + Op.POP(Op.CALL(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, value=0x0, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0))
        + Op.STOP + Op.STOP
    ),
    )
    pre[callee_2] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.CALLCODE(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, value=0x0, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0)
        + Op.STOP
    ),
    )
    pre[callee_3] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x24]
        + Op.CODECOPY(dest_offset=0x0, offset=0x13, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.POP(Op.CREATE2) + Op.STOP + Op.STOP + Op.INVALID
        + Op.POP(Op.CALLCODE(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, value=0x0, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0))
        + Op.STOP + Op.STOP
    ),
    )
    pre[callee_4] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.POP(Op.DELEGATECALL(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0))
        + Op.STOP + Op.STOP
    ),
    )
    pre[callee_5] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x22]
        + Op.CODECOPY(dest_offset=0x0, offset=0x13, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.POP(Op.CREATE2) + Op.STOP + Op.STOP + Op.INVALID
        + Op.POP(Op.DELEGATECALL(gas=Op.GAS, address=0xf000000000000000000000000000000000000000, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0))
        + Op.STOP + Op.STOP
    ),
    )
    pre[callee_6] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.POP(Op.STATICCALL(gas=Op.GAS, address=0xf200000000000000000000000000000000000000, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x100))
        + Op.SSTORE(key=0xa, value=Op.MLOAD(offset=0x0)) + Op.STOP
    ),
    )
    pre[callee_7] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x29]
        + Op.CODECOPY(dest_offset=0x0, offset=0x11, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.CREATE2 + Op.STOP + Op.INVALID
        + Op.POP(Op.STATICCALL(gas=Op.GAS, address=0xf200000000000000000000000000000000000000, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x100))
        + Op.SSTORE(key=0xa, value=Op.MLOAD(offset=0x0)) + Op.STOP + Op.STOP
    ),
    )
    pre[sender] = Account(balance=0x56bc75e2d63100000, nonce=0)
    pre[contract] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.CALL(gas=Op.GAS, address=Op.CALLDATALOAD(offset=0x0), value=0x0, args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0)
        + Op.STOP
    ),
    )
    pre[callee_8] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x23]
        + Op.CODECOPY(dest_offset=0x0, offset=0x13, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.POP(Op.CREATE2) + Op.STOP + Op.STOP + Op.INVALID
        + Op.SSTORE(key=0x0, value=Op.ADDRESS)
        + Op.SSTORE(key=0x1, value=Op.BALANCE(address=Op.ADDRESS))
        + Op.SSTORE(key=0x2, value=Op.ORIGIN) + Op.SSTORE(key=0x3, value=Op.CALLER)
        + Op.SSTORE(key=0x4, value=Op.CALLVALUE)
        + Op.SSTORE(key=0x5, value=Op.CALLDATASIZE)
        + Op.SSTORE(key=0x6, value=Op.CODESIZE)
        + Op.SSTORE(key=0x7, value=Op.GASPRICE) + Op.STOP + Op.STOP
    ),
    )
    pre[callee_9] = Account(
        balance=0,
        nonce=0,
        code=(
        Op.PUSH1[0x0] + Op.PUSH1[0x29]
        + Op.CODECOPY(dest_offset=0x0, offset=0x11, size=Op.DUP1) + Op.PUSH1[0x0]
        + Op.PUSH1[0x0] + Op.CREATE2 + Op.STOP + Op.INVALID
        + Op.MSTORE(offset=0x0, value=Op.ADDRESS)
        + Op.MSTORE(offset=0x20, value=Op.BALANCE(address=Op.ADDRESS))
        + Op.MSTORE(offset=0x40, value=Op.ORIGIN)
        + Op.MSTORE(offset=0x60, value=Op.CALLER)
        + Op.MSTORE(offset=0x80, value=Op.CALLVALUE)
        + Op.MSTORE(offset=0xa0, value=Op.CALLDATASIZE)
        + Op.MSTORE(offset=0xc0, value=Op.CODESIZE)
        + Op.MSTORE(offset=0xe0, value=Op.GASPRICE)
        + Op.RETURN(offset=0x0, size=0x100) + Op.STOP + Op.STOP
    ),
    )

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x45a915e4d060149eb4365960e6a7a45f334393093061116b197e3240065ff2d8"
        ),
        to=contract,
        data=tx_data,
        gas_limit=600000,
        gas_price=10,
        nonce=0,
        value=0,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
